create table promotion_groups(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisations(id),name text not null,created_at timestamptz not null default now(),unique(organisation_id,id),unique(organisation_id,name));
create table promotion_group_families(organisation_id uuid not null references organisations(id),group_id uuid not null,family_id uuid not null,primary key(group_id,family_id),foreign key(organisation_id,group_id) references promotion_groups(organisation_id,id),foreign key(organisation_id,family_id) references product_families(organisation_id,id));
create table promotions(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisations(id),group_id uuid not null,name text not null,promotion_type text not null default 'multibuy' check(promotion_type in('multibuy')),qualifying_quantity integer not null check(qualifying_quantity>1),bundle_price numeric(12,2) not null check(bundle_price>=0),starts_at timestamptz,ends_at timestamptz,active boolean not null default true,created_at timestamptz not null default now(),foreign key(organisation_id,group_id) references promotion_groups(organisation_id,id),unique(organisation_id,id));
create table sale_promotions(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisations(id),sale_id uuid not null,promotion_id uuid not null,description text not null,discount_total numeric(12,2) not null check(discount_total>=0),foreign key(organisation_id,sale_id) references sales(organisation_id,id),foreign key(organisation_id,promotion_id) references promotions(organisation_id,id));
create index promotion_groups_org_idx on promotion_groups(organisation_id);create index promotions_active_idx on promotions(organisation_id,active) where active;create index sale_promotions_sale_idx on sale_promotions(sale_id);
do $$ declare n text;begin foreach n in array array['promotion_groups','promotion_group_families','promotions','sale_promotions'] loop execute format('alter table %I enable row level security',n);execute format('alter table %I force row level security',n);execute format('create policy tenant_isolation on %I for all using(organisation_id=(select app_current_organisation_id())) with check(organisation_id=(select app_current_organisation_id()))',n);end loop;end $$;
grant select,insert,update on promotion_groups,promotion_group_families,promotions,sale_promotions to counter_app;
